/** Filings derive FROM registrations: one completed artifact per past cycle,
 *  one open task per renewal-due/lapsed registration — never orphaned. */
export const filings = registrations.flatMap((r) => {
  const out = [];
  // the completed artifact from the registration's last cycle
  out.push({
    $type: "Filing",
    id: `fil_done_${r.id.slice(4)}`,
    registrationId: r.id,
    companyId: r.companyId,
    company: r.company,
    jurisdiction: r.jurisdiction,
    registry: r.registry,
    kind:
      r.registry === "sam-uei"
        ? "sam-registration-renewal"
        : r.registry === "sos-annual-report"
          ? "annual-report"
          : r.registry === "boi-report"
            ? "boi-initial-report"
            : "license-application",
    status: "filed",
    filedAt: r.registeredAt,
    example: true,
    exampleNote: EXAMPLE_NOTE,
  });
  // the open task where the calendar says one is due
  if (r.status === "renewal-due" || r.status === "lapsed") {
    out.push({
      $type: "Filing",
      id: `fil_open_${r.id.slice(4)}`,
      registrationId: r.id,
      companyId: r.companyId,
      company: r.company,
      jurisdiction: r.jurisdiction,
      registry: r.registry,
      kind: r.registry === "boi-report" ? "boi-updated-report" : "renewal",
      status: r.status === "lapsed" ? "overdue" : "open",
      dueAt: r.renewsAt,
      example: true,
      exampleNote: EXAMPLE_NOTE,
    });
  }
  return out;
});

