export function getRegistration(id) {
  const r = registrations.find((x) => x.id === id);
  if (!r) return undefined;
  return { ...r, filings: filings.filter((f) => f.registrationId === id).map((f) => f.id) };
}

export function getFiling(id) {
  return filings.find((x) => x.id === id);
}

export function getPermit(id) {
  return permits.find((x) => x.id === id);
}
